use crate::list::*;
#[test]
fn paged_formatted_exact_extent_preserves_full_source_and_four_locale_cells_at_original_64k(){
 use crate::{NativeEncodeControl,paged_text::PagedText};
 let fixture:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../../../📋️list/🧪️tests/🧫️fixtures/🏷️formatted-exact-extent.json")).unwrap();assert_eq!(fixture["maximumAllocationBytes"],65536);assert_eq!(fixture["maximumItems"],1);assert_eq!(fixture["maximumBytes"],4096);assert_eq!(fixture["payloadBytes"],8194);assert_eq!(fixture["originalWireBytes"],8194);
 let value="x".repeat(8194);let pointer=value.as_ptr();let original=crate::staged_rig::source(value);let mut wire=vec![b' ';8194];wire[0]=b'1';wire[1]=b'7';let wire=crate::staged_rig::source(wire);let mut outputs:[Option<PagedText<{isize::MAX as usize}>>;5]=std::array::from_fn(|_|None);let bind=crate::staged_rig::encoder::projection_work(original.borrow()).unwrap();let wire_bind=crate::staged_rig::encoder::projection_work(wire.borrow()).unwrap();let plans:[(usize,u64);5]=std::array::from_fn(|index|if index==0{(8194,wire_bind)}else{let en=fixture["matrix"][index-1]=="En";(fixture[if en{"expectedEnBytes"}else{"expectedDeBytes"}].as_u64().unwrap()as usize,bind)});let stock=crate::staged_rig::Stock::for_outputs::<{isize::MAX as usize}>(&plans,65536,64).unwrap();let mut bank=crate::staged_rig::EncodeBank::new(stock,false);let admitted=bank.run(65536,64,|turn,control|{
 outputs[0]=Some(crate::staged_rig::encode_success(&wire,control,turn,16384,"","")?);
 for index in 1..5{let en=fixture["matrix"][index-1]=="En";let(prefix,suffix)=if en{("Set label to ","")}else{("Beschriftung auf "," setzen")};assert_eq!(prefix,fixture[if en{"prefixEn"}else{"prefixDe"}].as_str().unwrap());assert_eq!(suffix,fixture[if en{"suffixEn"}else{"suffixDe"}].as_str().unwrap());outputs[index]=Some(crate::staged_rig::encode_success(&original,control,turn,16384,prefix,suffix)?);} let admitted=control.owned_bytes();assert_eq!(original.borrow().get().as_ptr(),pointer);let retained=outputs.iter().map(|value|value.as_ref().unwrap().allocated_bytes()).sum::<usize>();assert_eq!(outputs[0].as_ref().unwrap().borrow().unwrap().byte_len(),8194);
 for(index,owner)in outputs.iter().enumerate().skip(1){let en=fixture["matrix"][index-1]=="En";let expected=fixture[if en{"expectedEnBytes"}else{"expectedDeBytes"}].as_u64().unwrap()as usize;let text=owner.as_ref().unwrap().borrow().unwrap();assert_eq!(text.byte_len(),expected);let(prefix,suffix)=if en{("Set label to ","")}else{("Beschriftung auf "," setzen")};for(at,byte)in prefix.bytes().chain(original.borrow().get().bytes()).chain(suffix.bytes()).enumerate(){assert_eq!(text.byte_at(at),Some(byte));}}
 assert_eq!(retained,admitted);assert!(admitted<=65536);Ok(admitted)}).unwrap();let left=bank.finish();assert!(left.work<stock.work);let retained=outputs.iter().map(|value|value.as_ref().unwrap().allocated_bytes()).sum::<usize>();assert_eq!(retained,admitted);let mut disposed=0;for owner in outputs{disposed+=crate::staged_rig::close_text(owner.unwrap())}assert_eq!(disposed,retained);crate::staged_rig::close_source(wire);crate::staged_rig::close_source(original);
}

#[test]
fn paged_formatted_exact_extent_retains_every_refused_prefix_and_complete_utf8_borrow(){
 use crate::{NativeEncodeControl,RetireOwned,ValueError,ValueRefusalKind,paged_text::{PagedText,PagedTextEncodeFrame,PagedTextReadStep,PagedTextStage,TextReadSource,TextSourceByteReply,TextSourceByteComplete}};
 use std::sync::atomic::{AtomicUsize,Ordering};
 let fixture:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../../../📋️list/🧪️tests/🧫️fixtures/❌️formatted-exact-extent.json")).unwrap();assert_eq!(fixture["sourceBytes"],8194);assert_eq!(fixture["maximumAllocationBytes"],65536);assert_eq!(fixture["maximumItems"],1);assert_eq!(fixture["maximumBytes"],4096);assert_eq!(fixture["initialAllocationBytes"],4096);assert_eq!(fixture["interiorBytes"],256);let payload=fixture["shortText"].as_str().unwrap().repeat(fixture["longRepeat"].as_u64().unwrap()as usize)+fixture["longSuffix"].as_str().unwrap();assert_eq!(payload.len(),8194);
 struct Probe{body:String,mode:u8,reads:AtomicUsize}
 impl TextReadSource for Probe{
  fn byte_len(&self)->usize{let count=self.reads.load(Ordering::SeqCst);match self.mode{5 if count>=self.body.len()+6=>6,6 if count<6=>6,_=>self.body.len()}}
  fn byte_at(&self,index:usize)->Option<u8>{let count=self.reads.fetch_add(1,Ordering::SeqCst);if self.mode==6&&count<6{"ä🧩".as_bytes().get(index).copied()}else{self.body.as_bytes().get(index).copied()}}
  fn read_recorded(&self,mut reply:TextSourceByteReply<'_,'_>)->TextSourceByteComplete{let _=reply.performed(1).expect("original Work receipt must accept the source report");if self.mode==9{self.reads.fetch_add(1,Ordering::SeqCst);reply.complete(Err(ValueError::literal(ValueRefusalKind::InvalidValue,"original formatter refused")),1)}else{let value=self.byte_at(reply.index());reply.complete(Ok(value),1)}}
 }
 impl RetireOwned for Probe{type RetirementCursor=<(String,u8,usize) as RetireOwned>::RetirementCursor;fn retirement_ready(&self)->bool{self.body.retirement_ready()}fn retirement_seed(self)->Self::RetirementCursor{(self.body,self.mode,self.reads.into_inner()).retirement_seed()}fn retirement_birth_bytes(&self)->Option<usize>{self.retirement_ready().then_some(std::mem::size_of::<Self::RetirementCursor>())}fn controlled_retirement_supported()->bool{<(String,u8,usize) as RetireOwned>::controlled_retirement_supported()}}

 use crate::staged_rig::encoder::{EncodeBank,Stock,Payment,projection_work,drive_one_snapshot,return_loan,close_producer,take_frame_reply,retire_published_failure,retire_value};use crate::paged_text::PagedTextEncodeProducer;
 for(mode_index,mode)in fixture["modes"].as_array().unwrap().iter().enumerate(){let mode=mode.as_str().unwrap();let source_body=if mode=="duplicate-formatter"{"short".to_owned()}else{payload.clone()};let pointer=source_body.as_ptr();let input_len=source_body.len();let original=crate::staged_rig::source(Probe{body:source_body,mode:mode_index as u8,reads:AtomicUsize::new(0)});let foreign=if mode=="duplicate-formatter"{Some(crate::staged_rig::source(Probe{body:"other".to_owned(),mode:8,reads:AtomicUsize::new(0)}))}else{None};let maximum=if mode=="initial4096"{4096}else{65536};let stock=Stock::for_outputs::<{isize::MAX as usize}>(&[(input_len,projection_work(original.borrow()).unwrap())],65536,64).unwrap();let mut bank=EncodeBank::new(stock,false);let mut output:Option<PagedText<{isize::MAX as usize}>>=None;
 bank.run(maximum,64,|turn,control|{let mut producer=PagedTextEncodeProducer::new(turn.witness(),original.borrow(),&mut output,if mode=="segment-one-short"{8193}else{16384},"","")?;let mut frame=PagedTextEncodeFrame::new(control,turn,&mut producer)?;let mut stopped=false;let mut did_cancel=false;let mut refused=false;
 for _ in 0..100000{let p=frame.producer().unwrap();let stage=p.stage();let position=p.phase_progress().0;if mode=="count-cancel"&&stage==PagedTextStage::Validating&&position==0||matches!(mode,"declaration-cancel"|"ignored-declaration-cancel")&&stage==PagedTextStage::Copying&&position==0||mode=="interior-cancel"&&stage==PagedTextStage::Copying&&position==256{did_cancel=true;stopped=true;break}
 if mode=="duplicate-formatter"&&stage==PagedTextStage::Copying&&position==5{let issuer=crate::OriginalSourceTurnIssuer::new();let wrong=issuer.issue().unwrap();let d=frame.demand()?.0;let mut error=Some(frame.advance_body(control,&wrong,crate::staged_rig::grant(d)).expect_err("foreign original Source was accepted"));assert_eq!(frame.producer().unwrap().phase_progress().0,5);assert_eq!(foreign.as_ref().unwrap().borrow().get().body,"other");retire_value(&mut error,control,turn)?;stopped=true;break}
 let(operation,success,actual)=drive_one_snapshot(&mut frame,control,turn)?;if !success{refused=true;stopped=true;break}if operation==crate::paged_text::PagedTextEncodeOperation::Reserve&&actual.unwrap().progress==Default::default(){stopped=true;break}assert_ne!(operation,crate::paged_text::PagedTextEncodeOperation::Publish,"refused original formatter was published: {mode}");}
 assert!(stopped,"original formatter never reached its refusal or cancellation: {mode}");assert_eq!(original.borrow().get().body.as_ptr(),pointer);let p=frame.producer().unwrap();let retained=p.retained_capacity();assert_eq!(retained,control.owned_bytes());if mode=="interior-cancel"{assert_eq!(p.retained_len(),256)}if mode=="second-short"{assert_eq!(p.retained_len(),6)}if mode=="duplicate-formatter"{assert_eq!(p.retained_len(),5)}if matches!(mode,"count-cancel"|"declaration-cancel"|"ignored-declaration-cancel"|"segment-one-short"|"second-long"|"ignored-formatter-error"){assert_eq!(retained,0)}if mode=="initial4096"{assert_eq!(p.retained_len(),0);assert!(retained>0&&retained<=4096)}
 if mode=="ignored-formatter-error"{assert!(refused);let reads=original.borrow().get().reads.load(Ordering::SeqCst);let d=frame.demand()?.0;let _=frame.advance_body(control,turn,crate::staged_rig::grant(d))?;assert_eq!(original.borrow().get().reads.load(Ordering::SeqCst),reads);assert!(frame.reply().unwrap().is_err());}
 let mut published=None;if refused{take_frame_reply(&mut frame,control,turn,&mut published)?}return_loan(&mut frame,control,turn)?;drop(frame);producer.begin_close();if did_cancel&&mode=="ignored-declaration-cancel"{let mut error=Some(match PagedTextEncodeFrame::new(control,turn,&mut producer){Err(error)=>error,Ok(_)=>panic!("ignored cancellation restarted the producer")});retire_value(&mut error,control,turn)?;}close_producer(&mut producer,control,turn)?;assert!(producer.terminal_is_empty());drop(producer);if published.is_some(){retire_published_failure(&mut published,control,turn)?}Ok(())}).unwrap();let paid=bank.finish();assert_eq!(paid.submitted.retained_capacity_bytes,paid.submitted.released_bytes);assert!(output.is_none());if let Some(foreign)=foreign{crate::staged_rig::close_source(foreign)}crate::staged_rig::close_source(original);
 }
 for text in [fixture["shortText"].as_str().unwrap(),payload.as_str()]{let original=crate::staged_rig::source(text.to_owned());let stock=Stock::for_outputs::<{isize::MAX as usize}>(&[(text.len(),projection_work(original.borrow()).unwrap())],65536,64).unwrap();let mut bank=EncodeBank::new(stock,false);let mut paged=None;
 bank.run(65536,64,|turn,control|{let(mut owner,mut inline)=crate::staged_rig::encode_inline_success::<_,{isize::MAX as usize}>(&original,control,turn,8194,"","")?;if text.len()<=128{assert!(owner.is_none());assert_eq!(inline.as_ref().unwrap().borrow()?,text);assert_eq!(control.owned_bytes(),0);let d=crate::RetirementDemand{copy_bytes:std::mem::size_of_val(&inline),depth:1,..Default::default()};let mut pay=Payment::default();pay.begin(control,d,1)?;pay.stage(control,|_,_,effect|{assert!(effect.performed(1)?);let mut cell=inline.take().unwrap();assert!(cell.close_one(1));assert!(cell.borrow().is_err());drop(cell);Ok(Some(crate::RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;assert!(pay.post(control)?);pay.finish(control)?;}else{assert!(inline.is_none());let actual=owner.as_ref().unwrap();assert_eq!(actual.borrow()?.byte_len(),8194);assert!(actual.borrow()?.bytes().eq(original.borrow().get().bytes()));assert_eq!(actual.allocated_bytes(),control.owned_bytes());paged=owner.take();}Ok(())}).unwrap();bank.finish();if let Some(owner)=paged{let retained=owner.allocated_bytes();assert_eq!(crate::staged_rig::close_text(owner),retained)}crate::staged_rig::close_source(original);
 }

}


/// 🧾️ A real construction reply survives unwind in the original paged owner before physical allocation.
#[test]
fn paged_text_page_allocation_recovers_the_recorded_original_reply(){
 use crate::paged_text::{PagedTextEncodeProducer,PagedTextEncodeFrame,PagedTextEncodeOperation};use crate::staged_rig::encoder::{EncodeBank,Stock,projection_work,drive_one,return_loan,close_producer};use std::sync::atomic::Ordering;
 let fixture:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../../../📋️list/🧪️tests/🧫️fixtures/🏷️formatted-exact-extent.json")).unwrap();let limit=fixture["payloadBytes"].as_u64().unwrap()as usize;let original=crate::staged_rig::source("x".repeat(limit));let stock=Stock::for_outputs::<{isize::MAX as usize}>(&[(limit,projection_work(original.borrow()).unwrap())],65536,64).unwrap();let mut bank=EncodeBank::new(stock,false);let interrupt=bank.grant_interrupt();let allocations=bank.allocation_posts();let mut output=None;
 bank.run(65536,64,|turn,control|{let mut producer=PagedTextEncodeProducer::<_,{isize::MAX as usize}>::new(turn.witness(),original.borrow(),&mut output,16384,"","")?;let mut frame=PagedTextEncodeFrame::new(control,turn,&mut producer)?;let mut reserved=false;for _ in 0..100000{if frame.operation()?==PagedTextEncodeOperation::Reserve{reserved=true;break}drive_one(&mut frame,control,turn)?;}assert!(reserved);let(demand,_,_)=frame.demand()?;let grant=crate::staged_rig::grant(demand);assert!(demand.capacity_bytes>0);assert_eq!(allocations.load(Ordering::SeqCst),0);interrupt.store(true,Ordering::SeqCst);let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||frame.advance_body(control,turn,grant)));assert!(interrupted.is_err());assert_eq!(frame.producer().unwrap().retained_capacity(),0);assert_eq!(frame.demand()?.0,demand);assert_eq!(allocations.load(Ordering::SeqCst),0);
 let(result,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||drive_one(&mut frame,control,turn));result?;assert_eq!(heap,(demand.capacity_bytes,0));assert_eq!(frame.producer().unwrap().retained_capacity(),demand.capacity_bytes);assert_eq!(control.owned_bytes(),demand.capacity_bytes);assert_eq!(allocations.load(Ordering::SeqCst),1);return_loan(&mut frame,control,turn)?;drop(frame);close_producer(&mut producer,control,turn)?;drop(producer);Ok(())}).unwrap();let paid=bank.finish();assert_eq!(paid.submitted.retained_capacity_bytes,paid.submitted.released_bytes);assert!(output.is_none());crate::staged_rig::close_source(original);}
